# length_distribution ----
## Setup ----
# 2 ages on 25-unit length bins from 0 to 500.
fine_edges <- seq(0, 500, 25)
length_probability <- FIMS:::length_distribution(
  c(100, 300), c(10, 30), fine_edges
)

## IO correctness ----
test_that("`length_distribution()` works with correct inputs", {
  #' @description Test that each row of `length_distribution()` sums to 1.
  expect_equal(
    object = rowSums(length_probability),
    expected = c(1, 1)
  )
  #' @description Test that `length_distribution()` gives the bin from 100 to 125 the normal probability between those lengths for a mean of 100 and an sd of 10.
  expect_equal(
    object = unname(length_probability[1, 5]),
    expected = stats::pnorm(125, 100, 10) - stats::pnorm(100, 100, 10)
  )
  #' @description Test that `length_distribution()` gives the bin from 250 to 275 the normal probability between those lengths for a mean of 300 and an sd of 30.
  expect_equal(
    object = unname(length_probability[2, 11]),
    expected = stats::pnorm(275, 300, 30) - stats::pnorm(250, 300, 30)
  )
})

## Edge handling ----
test_that("`length_distribution()` returns correct outputs for edge cases", {
  # 2 bins split at the mean, so the first bin holds all shorter lengths and
  # the last bin all longer lengths.
  #' @description Test that `length_distribution()` puts all lengths below the first interior edge in the first bin and all lengths above it in the last bin.
  expect_equal(
    object = as.vector(FIMS:::length_distribution(100, 10, c(90, 100, 110))),
    expected = c(0.5, 0.5)
  )
  #' @description Test that `length_distribution()` gives every bin a probability above 0, even far in the tails.
  expect_true(all(length_probability > 0))
})

## Error handling ----
# No built-in errors to test.

# age_to_length_conversion_derived ----
## Setup ----
# 1 age on 4 1-unit length bins from 0 to 4.
fine_probability <- matrix(c(0.1, 0.2, 0.3, 0.4), nrow = 1)

## IO correctness ----
test_that("`age_to_length_conversion_derived()` works with correct inputs", {
  #' @description Test that rebinning 1-unit bins to 2-unit bins with `rebin_weights()` sums the probabilities of the bins each new bin covers.
  expect_equal(
    object = as.vector(FIMS:::age_to_length_conversion_derived(
      fine_probability,
      FIMS:::rebin_weights(0:4, c(0, 2, 4))
    )),
    expected = c(0.3, 0.7)
  )
  #' @description Test that `rebin_weights()` splits a bin that straddles a new edge in proportion to its overlap, so half of the bin from 1 to 2 goes to each new bin.
  expect_equal(
    object = as.vector(FIMS:::age_to_length_conversion_derived(
      fine_probability,
      FIMS:::rebin_weights(0:4, c(0, 1.5, 4))
    )),
    expected = c(0.1 + 0.2 / 2, 0.2 / 2 + 0.3 + 0.4)
  )
  coarse_probability <- FIMS:::age_to_length_conversion_derived(
    length_probability,
    FIMS:::rebin_weights(fine_edges, seq(0, 500, 100))
  )
  #' @description Test that rebinning to coarser bins with `rebin_weights()` keeps each row of the age-to-length key summing to 1.
  expect_equal(
    object = rowSums(coarse_probability),
    expected = c(1, 1)
  )
})

## Edge handling ----
# No edge cases to test.

## Error handling ----
# No built-in errors to test.
